import java.io.*; import java.lang.reflect.*; import java.nio.charset.StandardCharsets; import java.nio.file.*;
import java.security.*; import java.text.*; import java.util.*; import java.util.regex.*;
import javax.crypto.*; import javax.crypto.spec.*; import javax.xml.parsers.*; import org.w3c.dom.*;
// One pass over library code a real app reaches at startup. Prints once, at the end.
public class Workload {
    static long sink; static StringBuilder errs = new StringBuilder();
    interface S { void run() throws Exception; }
    static void sec(String name, S s, boolean timing, StringBuilder out) {
        long t = System.nanoTime();
        try { s.run(); } catch (Throwable e) { errs.append(name).append(':').append(e.getClass().getSimpleName()).append(' '); }
        if (timing) out.append(name).append('=').append((System.nanoTime()-t)/1000).append("us ");
    }
    static void strings() { StringBuilder b = new StringBuilder(); for (int i=0;i<2000;i++){ b.append("item").append(i).append(','); }
        String s=b.toString(); for(String p: s.split(",")) sink+=p.toUpperCase(Locale.ROOT).hashCode()+p.trim().replace('i','j').length(); sink+=String.format(Locale.US,"%d %s %.3f %x",42,"x",1.5,255).length(); }
    static void collections() { Map<String,Integer> m=new HashMap<>(); TreeMap<String,List<Integer>> t=new TreeMap<>(); ArrayDeque<Integer> d=new ArrayDeque<>();
        for(int i=0;i<5000;i++){ String k="k"+(i%700); Integer o0=m.get(k); m.put(k,o0==null?i:o0+i); List<Integer> li=t.get(k); if(li==null){li=new ArrayList<>(); t.put(k,li);} li.add(i); d.add(i);}
        List<String> l=new ArrayList<>(m.keySet()); Collections.sort(l); Collections.shuffle(l,new Random(1)); l.sort(new Comparator<String>(){ public int compare(String a,String b){ int c=a.length()-b.length(); return c!=0?c:b.compareTo(a);} }); sink+=l.size()+d.size()+t.size(); }
    static void regex() { Pattern p=Pattern.compile("(\\w+)@(\\w+)\\.(com|org)"); String txt="a@b.com, foo@bar.org; x y z baz@qux.com"; for(int i=0;i<300;i++){ Matcher m=p.matcher(txt); while(m.find()) sink+=m.group(1).length(); sink+=txt.replaceAll("\\s+","_").length(); } }
    static void text() throws Exception { TimeZone tz=TimeZone.getTimeZone("America/Argentina/Buenos_Aires"); for(Locale l:new Locale[]{Locale.US,Locale.GERMANY,new Locale("es","AR"),Locale.JAPAN}){ SimpleDateFormat f=new SimpleDateFormat("EEE, d MMM yyyy HH:mm:ss Z",l); f.setTimeZone(tz); String d=f.format(new Date(1700000000000L)); sink+=f.parse(d).getTime(); DecimalFormat n=(DecimalFormat)NumberFormat.getInstance(l); sink+=n.format(1234567.891).length(); sink+=NumberFormat.getCurrencyInstance(l).format(9.5).length(); Collator c=Collator.getInstance(l); sink+=c.compare("árbol","zebra"); BreakIterator bi=BreakIterator.getWordInstance(l); bi.setText("Hello world, this is a test."); while(bi.next()!=BreakIterator.DONE) sink++; sink+=MessageFormat.format("{0} has {1,number,integer} items",new Object[]{"x",3}).length(); sink+=Calendar.getInstance(tz,l).get(Calendar.YEAR); } }
    static void icu() throws Exception { Class<?> c=Class.forName("android.icu.text.NumberFormat"); Object f=c.getMethod("getInstance",Locale.class).invoke(null,Locale.FRANCE); sink+=((String)c.getMethod("format",double.class).invoke(f,1234.5)).length(); Class<?> t=Class.forName("android.icu.util.ULocale"); sink+=t.getName().length(); Class<?> n=Class.forName("android.icu.text.Normalizer2"); Object o=n.getMethod("getNFCInstance").invoke(null); sink+=((String)n.getMethod("normalize",CharSequence.class).invoke(o,"é")).length(); }
    static void xml() throws Exception { StringBuilder b=new StringBuilder("<?xml version=\"1.0\"?><r>"); for(int i=0;i<500;i++) b.append("<e id=\"").append(i).append("\"><c>v").append(i).append("</c></e>"); b.append("</r>"); byte[] x=b.toString().getBytes("UTF-8");
        Document d=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new ByteArrayInputStream(x)); sink+=d.getElementsByTagName("e").getLength();
        final int[] cnt={0}; SAXParserFactory.newInstance().newSAXParser().parse(new ByteArrayInputStream(x), new org.xml.sax.helpers.DefaultHandler(){ @Override public void startElement(String u,String l,String q,org.xml.sax.Attributes a){cnt[0]++;}}); sink+=cnt[0];
        javax.xml.transform.Transformer tr=javax.xml.transform.TransformerFactory.newInstance().newTransformer(); StringWriter w=new StringWriter(); tr.transform(new javax.xml.transform.dom.DOMSource(d),new javax.xml.transform.stream.StreamResult(w)); sink+=w.toString().length(); }
    static void pull() throws Exception { Class<?> f=Class.forName("org.xmlpull.v1.XmlPullParserFactory"); Object fi=f.getMethod("newInstance").invoke(null); Object p=f.getMethod("newPullParser").invoke(fi); Class<?> pc=Class.forName("org.xmlpull.v1.XmlPullParser"); pc.getMethod("setInput",Reader.class).invoke(p,new StringReader("<a><b c=\"d\">t</b></a>")); Method n=pc.getMethod("next"); while(((Integer)n.invoke(p))!=1) sink++; }
    static void crypto() throws Exception { byte[] data=new byte[1<<16]; new Random(2).nextBytes(data); for(String a:new String[]{"MD5","SHA-1","SHA-256","SHA-512"}) sink+=MessageDigest.getInstance(a).digest(data)[0]; Mac m=Mac.getInstance("HmacSHA256"); m.init(new SecretKeySpec(new byte[32],"HmacSHA256")); sink+=m.doFinal(data)[0]; Cipher c=Cipher.getInstance("AES/CBC/PKCS5Padding"); c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(new byte[16],"AES"),new IvParameterSpec(new byte[16])); sink+=c.doFinal(data).length; SecureRandom r=new SecureRandom(); sink+=r.nextInt(5); sink+=Base64.getEncoder().encodeToString(data).length(); }
    static void tls() throws Exception { javax.net.ssl.SSLContext s=javax.net.ssl.SSLContext.getInstance("TLS"); s.init(null,null,null); sink+=s.getSupportedSSLParameters().getCipherSuites().length; sink+=s.getSocketFactory().getDefaultCipherSuites().length; sink+=Security.getProviders().length; }
    static class Bean { public int a=1; private String b="x"; public int getA(){return a;} public String getB(){return b;} }
    static void reflect() throws Exception { for(int i=0;i<300;i++){ Bean x=new Bean(); for(Method m:Bean.class.getMethods()) if(m.getName().startsWith("get")&&m.getParameterTypes().length==0&&m.getDeclaringClass()==Bean.class) sink+=String.valueOf(m.invoke(x)).length(); for(Field f:Bean.class.getDeclaredFields()){ f.setAccessible(true); sink+=f.getName().length(); } } Object prx=Proxy.newProxyInstance(Workload.class.getClassLoader(),new Class<?>[]{Runnable.class},(p,m,a)->null); ((Runnable)prx).run(); }
    static void files() throws Exception { File d=File.createTempFile("wl0",".d"); d.delete(); d.mkdirs(); File f=new File(d,"a.txt"); try(PrintWriter w=new PrintWriter(new FileWriter(f))){ for(int i=0;i<2000;i++) w.println("line "+i);} try(BufferedReader r=new BufferedReader(new FileReader(f))){ String l; while((l=r.readLine())!=null) sink+=l.length(); } Path p=f.toPath(); sink+=Files.readAllLines(p,StandardCharsets.UTF_8).size(); Files.copy(p,p.resolveSibling("b.txt")); try(java.util.zip.GZIPOutputStream z=new java.util.zip.GZIPOutputStream(new FileOutputStream(new File(d,"c.gz")))){ z.write(Files.readAllBytes(p)); } Properties q=new Properties(); q.setProperty("a","b"); q.store(new ByteArrayOutputStream(),"x"); for(File x:d.listFiles()) x.delete(); d.delete(); }
    static void pass(boolean timing, StringBuilder o) {
        sec("str",Workload::strings,timing,o); sec("coll",Workload::collections,timing,o); sec("re",Workload::regex,timing,o); sec("text",Workload::text,timing,o); sec("icu",Workload::icu,timing,o); sec("xml",Workload::xml,timing,o); sec("pull",Workload::pull,timing,o); sec("crypto",Workload::crypto,timing,o); sec("tls",Workload::tls,timing,o); sec("refl",Workload::reflect,timing,o); sec("file",Workload::files,timing,o);
    }
    public static void main(String[] a) { int passes=a.length>0?Integer.parseInt(a[0]):1; boolean t=a.length>1; StringBuilder o=new StringBuilder(); for(int i=0;i<passes;i++){ StringBuilder x=new StringBuilder(); pass(t,x); o=x; if(i>0)errs.setLength(0); } System.out.println(o+"err["+errs+"]"); System.out.flush(); }
}
